with lines as (select id, plan, effective_from, explode(tier_limits) as tier_value from price_tiers), enriched as (select *, stddev_samp(tier_value) over w_ordered as plan_stddev_samp_tier_value, max(tier_value) over w_ordered as plan_max_tier_value, stddev_samp(tier_value) over w_ordered as plan_stddev_samp_tier_value_2 from lines window w_ordered as (partition by plan)), with_windows as (select tier_value, plan_stddev_samp_tier_value, plan_max_tier_value, plan_stddev_samp_tier_value_2, cume_dist() over (partition by plan order by tier_value asc nulls first) as tier_value_cume_dist, rank() over (partition by plan order by plan_stddev_samp_tier_value_2 desc nulls first) as plan_stddev_samp_tier_value_2_rank from enriched where plan = 'pro'), filtered as (select tier_value, plan_max_tier_value, plan_stddev_samp_tier_value_2, round(tier_value, 1) as tier_value_rounded from with_windows where plan_stddev_samp_tier_value is not null), valid as (select *, greatest(tier_value_rounded, plan_stddev_samp_tier_value_2) as greatest_tier_value_rounded_plan_stddev_samp_tier_value_2 from filtered where plan_max_tier_value > 72) select tier_value, plan_max_tier_value, plan_stddev_samp_tier_value_2, tier_value_rounded from valid order by plan_stddev_samp_tier_value_2 desc nulls last;
